-- 可重复执行的示例菜单；不修改已有账号、价格、营业状态或订单。
-- 新商家沿用初始 merchant 账号的密码摘要，默认密码 merchant123。
START TRANSACTION;
UPDATE dishes d JOIN shops s ON s.id=d.shop_id JOIN users u ON u.id=s.owner_id SET d.image_path=CASE d.name WHEN '香辣鸡腿饭' THEN '/images/chicken-rice.webp' WHEN '番茄鸡蛋面' THEN '/images/tomato-noodles.webp' WHEN '柠檬茶' THEN '/images/lemon-tea.webp' END WHERE u.username='merchant' AND (d.image_path IS NULL OR d.image_path='') AND d.name IN ('香辣鸡腿饭','番茄鸡蛋面','柠檬茶');
COMMIT;
